class Parser(HTMLParser):
    def __init__(self):
        super().__init__(); self.tags=[]; self.external=[]
    def handle_starttag(self, tag, attrs):
        self.tags.append(tag)
        for k,v in attrs:
            if v and (v.startswith('http://') or v.startswith('https://')) and k not in {'xmlns'}:
                self.external.append((tag,k,v))
parser=Parser(); parser.feed(s)
